import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            int k = sc.nextInt();
            double[] probabilities = new double[n];
            for (int i = 0; i < n; i++) {
                probabilities[i] = sc.nextDouble();
            }

            int totalSubsets = 1 << n;
            double[] subsetSum = new double[totalSubsets];
            for (int mask = 0; mask < totalSubsets; mask++) {
                double sum = 0.0;
                for (int j = 0; j < n; j++) {
                    if ((mask & (1 << j)) != 0) {
                        sum += probabilities[j];
                    }
                }
                subsetSum[mask] = sum;
            }

            int activeCount = 0;
            for (double p : probabilities) {
                if (p > 1e-5) activeCount++;
            }

            if (activeCount <= k) {
                for (int i = 0; i < n; i++) {
                    double val = (probabilities[i] > 1e-5) ? 1.0 : 0.0;
                    System.out.print(val);
                    if (i + 1 != n) System.out.print(" ");
                }
                System.out.println();
                continue;
            }

            double[] dp = new double[totalSubsets];
            Arrays.fill(dp, 0.0);
            dp[0] = 1.0;

            for (int mask = 0; mask < totalSubsets; mask++) {
                int remaining_mask = (~mask) & (totalSubsets - 1);
                for (int i = 0; i < n; i++) {
                    if ((remaining_mask & (1 << i)) != 0 && probabilities[i] > 1e-5) {
                        int next_mask = mask | (1 << i);
                        dp[next_mask] += dp[mask] * probabilities[i] / subsetSum[remaining_mask];
                    }
                }
            }

            double[] result = new double[n];
            Arrays.fill(result, 0.0);
            for (int mask = 0; mask < totalSubsets; mask++) {
                int count_bits = Integer.bitCount(mask);
                if (count_bits != k) continue;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) {
                        result[i] += dp[mask];
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                System.out.print(result[i]);
                if (i + 1 != n) System.out.print(" ");
            }
            System.out.println();
        }
        sc.close();
    }
}
